True def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]
    # Complete the outer rectangle, plus any interior row or column with
    # three or more existing marks, using color 2 for the missing cells.
    active_rows = {
        r for r in range(r0, r1 + 1)
        if sum(grid[r][c] != bg for c in range(c0, c1 + 1)) >= 3
    }
    active_cols = {
        c for c in range(c0, c1 + 1)
        if sum(grid[r][c] != bg for r in range(r0, r1 + 1)) >= 3
    }
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1) or r in active_rows or c in active_cols:
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
